  ) v(product_id, col, from_md5, to_md5, from_text, to_text) loop
    if r.col not in ('description', 'description_en') then raise exception 'booking_161 ROLLBACK: sarake % ei sallittu', r.col; end if;
    if md5(r.from_text) <> r.from_md5 or md5(r.to_text) <> r.to_md5 then raise exception 'booking_161 ROLLBACK: sisäinen md5-virhe (tuote %, %)', r.product_id, r.col; end if;
    execute format('select %I from kb.products where id = $1', r.col) into cur using r.product_id;
    if cur is not distinct from r.to_text then skip := skip + 1; continue; end if;   -- jo ajettu (uudelleenajo ei tee mitään)
    if cur is distinct from r.from_text then
      raise exception 'booking_161 ROLLBACK: kb.products id % sarake % ei vastaa odotettua tekstiä (md5 %, odotettu %). Ei muutoksia.', r.product_id, r.col, md5(cur), r.from_md5;
    end if;
    ids := ids || r.product_id; cols := cols || r.col; froms := froms || r.from_text; tos := tos || r.to_text;
  end loop;
  -- 2) päivitys (tarkka tekstivertailu myös WHERE-ehdossa; trigger zz_site_text_sync kirjaa sivutekstin uuden version)
  for k in 1 .. coalesce(array_length(ids, 1), 0) loop
    execute format('update kb.products set %I = $1 where id = $2 and %I = $3', cols[k], cols[k]) using tos[k], ids[k], froms[k];
    get diagnostics rc = row_count;
    if rc <> 1 then raise exception 'booking_161 ROLLBACK: päivitys epäonnistui (tuote %, %)', ids[k], cols[k]; end if;
    n := n + 1;
  end loop;
  raise notice 'booking_161 ROLLBACK: päivitetty % kenttää, jo valmiina %', n, skip;
end $m161$;
